    @Override
    public <T extends RESTResponse> T execute(HTTPRequest request, Class<T> responseType, Consumer<ErrorResponse> errorHandler, Consumer<Map<String, String>> responseHeaders) {
        // roundTripSerialize before intercepting so we modify the deserialized response
        Object body = roundTripSerialize(request.body(), "request");
        HTTPRequest req = ImmutableHTTPRequest.builder().from(request).body(body).build();
        T response = super.execute(req, responseType, errorHandler, responseHeaders);
        response = roundTripSerialize(response, "response");
        // Add scan planning mode to table config for LoadTableResponse
        if (response instanceof LoadTableResponse) {
            return castResponse(responseType, withPlanningMode((LoadTableResponse) response, RESTCatalogProperties.ScanPlanningMode.SERVER.modeName()));
        }
        return response;
    }
})
